// All game data in one object. To add a tree: create data/trees/<id>.js, import it here,
// and add its id to rules.treeOrder. Mutagens are listed in data/mutagens.js. Skill text and
// per-rank numbers are in data/skillText.js, generated by tools/extract_skill_text.py. What adds
// up to the build-wide totals is in data/totals.js.
import rules from "./rules.js";
import skillSets from "./skillSets.js";
import mutagens from "./mutagens.js";
import skillText from "./skillText.js";
import totals from "./totals.js";
import combat from "./trees/combat.js";
import signs from "./trees/signs.js";
import alchemy from "./trees/alchemy.js";
import general from "./trees/general.js";

export default {
  rules,
  skillSets,
  mutagens,
  skillText,
  totals,
  trees: { combat, signs, alchemy, general }
};
